package com.bankease.config;
import com.bankease.repository.UserRepository; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.core.userdetails.*; 
@Configuration public class AuthManagerConfig{@Bean UserDetailsService userDetailsService(UserRepository repo){return username->repo.findByEmail(username.toLowerCase()).map(u->User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).disabled(!u.isEnabled()).build()).orElseThrow(()->new UsernameNotFoundException("User not found"));}@Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();}}